	private void add(List<Statement> statements) {
		try (var connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (Statement statement : statements) {
				connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
						statement.getContext());
			}
			connection.commit();
		}
	}

	private void remove(List<Statement> statements) {
		try (var connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (Statement statement : statements) {
				connection.removeStatements(statement.getSubject(), statement.getPredicate(), statement.getObject(),
						statement.getContext());
			}
			connection.commit();
		}
	}

	private SailDataset snapshot() {
		return store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT);
	}

	private long nativeMapSize(TxnManager manager) throws Exception {
		return manager.doWith((stack, transaction) -> {
			MDBEnvInfo information = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(mdb_txn_env(transaction), information));
			return information.me_mapsize();
		});
	}

	private List<Long> eligibleFreeIds() throws Exception {
		return values().getTxnManager().doWith((stack, transaction) -> {
			var db = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, "free_ids", 0, db));
			var pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(transaction, db.get(0), pointer));
			long cursor = pointer.get(0);
			try {
				List<Long> eligible = new ArrayList<>();
				MDBVal key = MDBVal.calloc(stack);
				MDBVal data = MDBVal.calloc(stack);
				int result = mdb_cursor_get(cursor, key, data, MDB_FIRST);
				while (result == MDB_SUCCESS) {
					long id = values().data2id(key.mv_data().duplicate());
					// Legacy ordinals are globally reusable; v6 reuses only the requested reference family.
					if (values().getFormat().isLegacy() || ValueIds.getIdType(id) == ValueIds.T_URI) {
						eligible.add(id);
					}
					result = mdb_cursor_get(cursor, key, data, MDB_NEXT);
				}
				if (result != MDB_NOTFOUND) {
					E(result);
				}
				return eligible;
			} finally {
				mdb_cursor_close(cursor);
			}
		});
	}

	private void assertBoundStatements(SailDataset snapshot, List<Statement> expected) {
		for (Statement statement : expected) {
			List<Statement> actual = QueryResults.asList(snapshot.getStatements(statement.getSubject(),
					statement.getPredicate(), statement.getObject(), statement.getContext()));
			assertThat(actual).containsExactly(statement);
			assertThat(snapshot.getStatementCount(statement.getSubject(), statement.getPredicate(),
					statement.getObject(), statement.getContext())).isEqualTo(1);
		}
	}

