	private List<Long> nativeTermIds(NativeLmdbQuerySource source) throws Exception {
		List<Long> owners = new ArrayList<>();
		try (var records = source.tripleTerms(-1L, -1L, -1L)) {
			long[] row;
			while ((row = records.next()) != null) {
				owners.add(row[TripleIndex.CONTEXT_IDX]);
			}
		}
		return owners;
	}

