	@ParameterizedTest
	@CsvSource({ "2,false", "6,false" })
	void datasetCloseReleasesEveryPartiallyConsumedSpilledReader(int format, boolean inline) throws Exception {
		open(format, inline);
		List<Statement> statements = new ArrayList<>();
		for (int index = 0; index < 2400; index++) {
			statements.add(VALUES.createStatement(VALUES.createIRI("urn:lifetime:spill:" + index), PREDICATE,
					VALUES.createLiteral("spilled language owner", "en"), CONTEXT));
		}
		add(statements);
		try (var held = snapshot();
				var first = held.getStatements(null, null, null);
				var second = held.getStatements(null, PREDICATE,
						VALUES.createLiteral("spilled language owner", "EN"))) {
			// Each real legacy reader crosses the existing MapDB spill threshold while remaining partially consumed.
			for (int index = 0; index < 2048; index++) {
				assertThat(first.hasNext()).isTrue();
				first.next();
				assertThat(second.hasNext()).isTrue();
				second.next();
			}
			held.close();
			assertThat(first.hasNext()).isFalse();
			assertThat(second.hasNext()).isFalse();
		}
	}

	@ParameterizedTest
	@CsvSource({ "2,false", "6,false" })
	void datasetCloseCompletesBeforePartiallyConsumedReadersAreClosed(int format, boolean inline) throws Exception {
		open(format, inline);
		List<Statement> statements = new ArrayList<>();
		for (int index = 0; index < 2400; index++) {
			statements.add(VALUES.createStatement(VALUES.createIRI("urn:lifetime:close:" + index), PREDICATE,
					VALUES.createLiteral("spilled language owner", "en"), CONTEXT));
		}
		add(statements);
		try (var held = snapshot();
				var first = held.getStatements(null, null, null);
				var second = held.getStatements(null, PREDICATE,
						VALUES.createLiteral("spilled language owner", "EN"));
				var closer = Executors.newSingleThreadExecutor()) {
			for (int index = 0; index < 2048; index++) {
				assertThat(first.hasNext()).isTrue();
				first.next();
				assertThat(second.hasNext()).isTrue();
				second.next();
			}
			var close = closer.submit(held::close);
			try {
				close.get(10, TimeUnit.SECONDS);
				assertThat(first.hasNext()).isFalse();
				assertThat(second.hasNext()).isFalse();
			} finally {
				// Release caller-held read stamps after failure so the owner close is always joined.
				first.close();
				second.close();
				close.get(10, TimeUnit.SECONDS);
			}
		}
	}

	@ParameterizedTest
	@CsvSource({ "2,false", "6,false" })
	void actualDictionaryMapGrowthInvalidatesTheWholeHeldDataset(int format, boolean inline) throws Exception {
		open(format, inline, 64L * 1024 * 1024);
		add(doomedStatements());
		var triples = store.getBackingStore().getTripleStore();
		long triplesBefore = nativeMapSize(triples.getTxnManager());
		long valuesBefore = nativeMapSize(values().getTxnManager());
		try (var held = snapshot();
				var rows = held.getTriples(null, null, null);
				var worker = Executors.newSingleThreadExecutor()) {
			assertThat(rows.hasNext()).isTrue();
			CountDownLatch start = new CountDownLatch(1);
			var grown = worker.submit(() -> {
				start.await();
				int added = 0;
				while (nativeMapSize(values().getTxnManager()) == valuesBefore && added < 65_536) {
					List<Statement> batch = new ArrayList<>();
					for (int index = 0; index < 64; index++, added++) {
						batch.add(VALUES.createStatement(VALUES.createIRI("urn:lifetime:dictionary-growth:" + added),
								PREDICATE, VALUES.createLiteral("dictionary growth " + added + "x".repeat(8192)),
								CONTEXT));
					}
					add(batch);
				}
				return added;
			});
			start.countDown();
			int inserted = grown.get(30, TimeUnit.SECONDS);
			assertThat(nativeMapSize(values().getTxnManager())).isGreaterThan(valuesBefore);
			assertThat(nativeMapSize(triples.getTxnManager())).isEqualTo(triplesBefore);
			assertThatThrownBy(rows::next).isInstanceOf(SailException.class)
					.hasMessageContaining("SNAPSHOT")
					.hasMessageContaining("retry");
			assertThat(rows.hasNext()).isFalse();
			assertThatThrownBy(() -> held.getStatements(null, null, null)).isInstanceOf(SailException.class);
			assertThatThrownBy(held::getNamespaces).isInstanceOf(SailException.class);
			try (var fresh = snapshot()) {
				assertThat(fresh.getStatementCount(null, PREDICATE, null, CONTEXT)).isEqualTo(inserted + 1);
			}
		}
	}

